#include <utility>
#include <string>

int main() {
    // Direct construction
    std::pair<int, std::string> p1(42, "Answer");

    // Accessing public members directly
    int value = p1.first;
    std::string label = p1.second;

    // Using make_pair for deduction
    auto p2 = std::make_pair(3.14, 'c');

    // Using type aliases (introspection)
    using FirstType = decltype(p1)::first_type;
    // FirstType is int
}
